using System;
using System.Collections.Generic;

namespace AdaptOrDeity.Sim.Modules
{
    /// <summary>
    /// Static description of one CellML module version compiled to a kernel. Generated by tools/kernelgen.
    /// Variable indices into <see cref="KernelBatch"/> arrays are positions in <see cref="States"/>,
    /// <see cref="Externals"/> and <see cref="Algebraic"/>.
    /// </summary>
    public sealed class KernelDescriptor
    {
        public KernelDescriptor(
            string moduleType,
            string version,
            string component,
            string licence,
            string sourceSha256,
            VariableInfo[] states,
            VariableInfo[] externals,
            VariableInfo[] algebraic,
            int[] stateInitExternal,
            double[] stateInitLiteral,
            PortInfo[] ports,
            IReadOnlyDictionary<string, IReadOnlyDictionary<string, double>> instances,
            int[]? groupExternals = null)
        {
            if (stateInitExternal.Length != states.Length || stateInitLiteral.Length != states.Length)
                throw new ArgumentException("one initial-value entry per state required");
            ModuleType = moduleType;
            Version = version;
            Component = component;
            Licence = licence;
            SourceSha256 = sourceSha256;
            States = states;
            Externals = externals;
            Algebraic = algebraic;
            StateInitExternal = stateInitExternal;
            StateInitLiteral = stateInitLiteral;
            Ports = ports;
            Instances = instances;
            var group = new bool[externals.Length];
            foreach (int i in groupExternals ?? Array.Empty<int>())
                group[i] = true;
            _groupExternal = group;
            _externalIndex = IndexByName(externals);
            _stateIndex = IndexByName(states);
            _algebraicIndex = IndexByName(algebraic);
        }

        private readonly bool[] _groupExternal;

        /// <summary>
        /// Whether external <paramref name="index"/> is a group input: a kernel reads it once per call, from the first
        /// instance of the range, so it must hold the same value for every instance passed in one call. The others are
        /// read per instance.
        /// </summary>
        public bool IsGroupExternal(int index) => _groupExternal[index];

        public string ModuleType { get; }

        /// <summary>Module version directory name (the config's <c>module_subtype</c>).</summary>
        public string Version { get; }

        /// <summary>CellML component name.</summary>
        public string Component { get; }

        /// <summary>SPDX licence identifier from the module config.</summary>
        public string Licence { get; }

        /// <summary>SHA-256 over the module's cellml, units and config files at generation time.</summary>
        public string SourceSha256 { get; }

        public IReadOnlyList<VariableInfo> States { get; }

        /// <summary>Inputs supplied by the assembler: constants, boundary conditions and port inputs.</summary>
        public IReadOnlyList<VariableInfo> Externals { get; }

        /// <summary>Variables computed from states and externals.</summary>
        public IReadOnlyList<VariableInfo> Algebraic { get; }

        /// <summary>Per state: index of the external holding its initial value, or -1 to use the literal.</summary>
        public IReadOnlyList<int> StateInitExternal { get; }

        /// <summary>Per state: literal initial value, used when <see cref="StateInitExternal"/> is -1.</summary>
        public IReadOnlyList<double> StateInitLiteral { get; }

        public IReadOnlyList<PortInfo> Ports { get; }

        /// <summary>Parameter sets from the module's <c>instances/</c> folder: instance → variable → value (module units).</summary>
        public IReadOnlyDictionary<string, IReadOnlyDictionary<string, double>> Instances { get; }

        /// <summary>Stable key used in saves and probes, e.g. <c>tissue_diffusion_volume@nn</c>.</summary>
        public string Key => ModuleType + "@" + Version;

        public int ExternalIndex(string name) => _externalIndex.TryGetValue(name, out int i) ? i : -1;

        public int StateIndex(string name) => _stateIndex.TryGetValue(name, out int i) ? i : -1;

        public int AlgebraicIndex(string name) => _algebraicIndex.TryGetValue(name, out int i) ? i : -1;

        private readonly Dictionary<string, int> _externalIndex, _stateIndex, _algebraicIndex;

        private static Dictionary<string, int> IndexByName(VariableInfo[] list)
        {
            var index = new Dictionary<string, int>(list.Length);
            for (int i = 0; i < list.Length; i++)
                if (!index.ContainsKey(list[i].Name))
                    index[list[i].Name] = i;
            return index;
        }
    }
}
